create table if not exists public.ongoing_service_records (
  id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete restrict, project_id uuid not null references public.projects(id) on delete restrict, project_service_id uuid not null references public.project_services(id) on delete restrict, handover_record_id uuid not null references public.handover_records(id) on delete restrict, documentation_record_id uuid not null references public.documentation_records(id) on delete restrict, stabilization_record_id uuid not null references public.stabilization_records(id) on delete restrict, observation_record_id uuid not null references public.observation_records(id) on delete restrict, deployment_record_id uuid not null references public.deployment_records(id) on delete restrict, implementation_record_id uuid not null references public.implementation_records(id) on delete restrict, delivery_activation_id uuid not null references public.delivery_activations(id) on delete restrict, entitlement_id uuid not null references public.entitlements(id) on delete restrict, ongoing_service_reference text not null check (length(btrim(ongoing_service_reference)) between 8 and 256), idempotency_key text not null check (length(btrim(idempotency_key)) between 8 and 128), service_scope_snapshot jsonb not null check (jsonb_typeof(service_scope_snapshot) = 'object'), billing_mode text not null check (billing_mode in ('MONTHLY','ANNUAL')), status text not null default 'ACTIVE' check (status in ('ACTIVE','PAUSED','COMPLETED','CANCELLED')), started_at timestamptz not null default timezone('utc',now()), paused_at timestamptz, completed_at timestamptz, cancelled_at timestamptz, status_reason text, created_by uuid not null references auth.users(id) on delete restrict, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()), unique(handover_record_id), unique(organization_id,idempotency_key), check(completed_at is null or completed_at >= started_at)
);
create index if not exists ongoing_service_records_project_status_idx on public.ongoing_service_records(project_id,status,created_at desc);
create index if not exists ongoing_service_records_handover_idx on public.ongoing_service_records(handover_record_id,created_at desc);
alter table public.audit_events add column if not exists ongoing_service_record_id uuid references public.ongoing_service_records(id) on delete set null;
alter table public.audit_events drop constraint if exists audit_events_event_type_valid;
alter table public.audit_events add constraint audit_events_event_type_valid check (event_type in ('membership_created','membership_activated','membership_role_changed','membership_suspended','membership_removed','invitation_created','invitation_accepted','invitation_revoked','invitation_expired','project_created','project_updated','project_archived','project_membership_created','project_membership_activated','project_membership_role_changed','project_membership_suspended','project_membership_removed','project_service_requested','project_service_updated','proposal_created','proposal_version_created','proposal_issued','proposal_accepted','proposal_rejected','proposal_cancelled','agreement_created','agreement_version_created','agreement_accepted','agreement_activated','agreement_terminated','payment_obligation_created','payment_obligation_cancelled','payment_obligation_expired','payment_attempt_created','payment_attempt_transitioned','entitlement_activated','entitlement_paused','entitlement_resumed','entitlement_expired','entitlement_cancelled','delivery_activation_activated','delivery_activation_paused','delivery_activation_resumed','delivery_activation_completed','delivery_activation_cancelled','implementation_initialized','implementation_paused','implementation_resumed','implementation_completed','implementation_cancelled','deployment_initialized','deployment_paused','deployment_resumed','deployment_completed','deployment_cancelled','observation_initialized','observation_paused','observation_resumed','observation_completed','observation_cancelled','stabilization_initialized','stabilization_paused','stabilization_resumed','stabilization_completed','stabilization_cancelled','documentation_initialized','documentation_paused','documentation_resumed','documentation_completed','documentation_cancelled','handover_initialized','handover_paused','handover_resumed','handover_completed','handover_cancelled','ongoing_service_initialized','ongoing_service_paused','ongoing_service_resumed','ongoing_service_completed','ongoing_service_cancelled'));
create index if not exists audit_events_ongoing_service_record_idx on public.audit_events(ongoing_service_record_id,created_at);
create or replace function public.set_ongoing_service_record_updated_at() returns trigger language plpgsql set search_path=public,pg_temp as $$ begin new.updated_at=timezone('utc',now()); return new; end; $$;
drop trigger if exists set_ongoing_service_records_updated_at on public.ongoing_service_records;
create trigger set_ongoing_service_records_updated_at before update on public.ongoing_service_records for each row execute procedure public.set_ongoing_service_record_updated_at();
create or replace function private.record_ongoing_service_audit(p_event_type text,p_organization_id uuid,p_project_id uuid,p_project_service_id uuid,p_handover_record_id uuid,p_entitlement_id uuid,p_ongoing_service_record_id uuid,p_metadata jsonb default '{}'::jsonb) returns void language plpgsql security definer set search_path=public,pg_temp as $$ begin insert into public.audit_events(event_type,actor_user_id,organization_id,project_id,project_service_id,handover_record_id,entitlement_id,ongoing_service_record_id,metadata) values(p_event_type,(select auth.uid()),p_organization_id,p_project_id,p_project_service_id,p_handover_record_id,p_entitlement_id,p_ongoing_service_record_id,coalesce(p_metadata,'{}'::jsonb)); end; $$;
revoke all on function private.record_ongoing_service_audit(text,uuid,uuid,uuid,uuid,uuid,uuid,jsonb) from public;
revoke execute on function private.record_ongoing_service_audit(text,uuid,uuid,uuid,uuid,uuid,uuid,jsonb) from anon;
create or replace function public.initialize_ongoing_service(p_handover_record_id uuid,p_ongoing_service_reference text,p_idempotency_key text,p_service_scope_snapshot jsonb,p_billing_mode text,p_actor_user_id uuid default null) returns public.ongoing_service_records language plpgsql security definer set search_path=public,private,pg_temp as $$
declare actor_id uuid; handover public.handover_records; documentation public.documentation_records; stabilization public.stabilization_records; observation public.observation_records; deployment public.deployment_records; implementation public.implementation_records; activation public.delivery_activations; entitlement public.entitlements; existing public.ongoing_service_records; created public.ongoing_service_records; ref text; idem text; mode text;
begin
 actor_id:=coalesce((select auth.uid()),p_actor_user_id); if actor_id is null or not exists(select 1 from auth.users where id=actor_id) then raise exception using errcode='42501',message='A valid trusted ongoing-service actor is required.'; end if;
 ref:=btrim(coalesce(p_ongoing_service_reference,'')); idem:=btrim(coalesce(p_idempotency_key,'')); mode:=upper(btrim(coalesce(p_billing_mode,''))); if length(ref)<8 or length(ref)>256 or length(idem)<8 or length(idem)>128 or mode not in('MONTHLY','ANNUAL') then raise exception using errcode='22023',message='Ongoing-service identity or billing mode is invalid.'; end if; if jsonb_typeof(coalesce(p_service_scope_snapshot,'{}'::jsonb))<>'object' then raise exception using errcode='22023',message='Ongoing-service scope must be a JSON object.'; end if;
 select * into handover from public.handover_records where id=p_handover_record_id for share; if not found or handover.status<>'COMPLETED' then raise exception using errcode='22023',message='Ongoing service requires a completed handover record.'; end if;
 select * into documentation from public.documentation_records where id=handover.documentation_record_id for share; if not found or documentation.status<>'ACTIVE' then raise exception using errcode='22023',message='Ongoing service requires active documentation.'; end if;
 select * into stabilization from public.stabilization_records where id=handover.stabilization_record_id for share; if not found or stabilization.status<>'ACTIVE' then raise exception using errcode='22023',message='Ongoing service requires active stabilization.'; end if;
 select * into observation from public.observation_records where id=handover.observation_record_id for share; if not found or observation.status<>'ACTIVE' then raise exception using errcode='22023',message='Ongoing service requires active observation.'; end if;
 select * into deployment from public.deployment_records where id=handover.deployment_record_id for share; if not found or deployment.status<>'ACTIVE' then raise exception using errcode='22023',message='Ongoing service requires active deployment.'; end if;
 select * into implementation from public.implementation_records where id=handover.implementation_record_id for share; if not found or implementation.status<>'ACTIVE' then raise exception using errcode='22023',message='Ongoing service requires active implementation.'; end if;
 select * into activation from public.delivery_activations where id=handover.delivery_activation_id for share; if not found or activation.status<>'ACTIVE' then raise exception using errcode='22023',message='Ongoing service requires active delivery activation.'; end if;
 select * into entitlement from public.entitlements where id=handover.entitlement_id for share; if not found or entitlement.status<>'ACTIVE' then raise exception using errcode='22023',message='Ongoing service requires active entitlement.'; end if;
 if handover.organization_id is distinct from entitlement.organization_id or handover.project_id is distinct from entitlement.project_id or handover.project_service_id is distinct from entitlement.project_service_id or handover.documentation_record_id is distinct from documentation.id or handover.stabilization_record_id is distinct from stabilization.id or handover.observation_record_id is distinct from observation.id or handover.deployment_record_id is distinct from deployment.id or handover.implementation_record_id is distinct from implementation.id or handover.delivery_activation_id is distinct from activation.id or handover.entitlement_id is distinct from entitlement.id then raise exception using errcode='42501',message='Ongoing-service upstream relationships do not match.'; end if;
 select * into existing from public.ongoing_service_records where organization_id=handover.organization_id and idempotency_key=idem for update; if found then if existing.handover_record_id is distinct from handover.id or existing.ongoing_service_reference is distinct from ref then raise exception using errcode='23505',message='Ongoing-service idempotency key was already used for a different record.'; end if; return existing; end if;
 insert into public.ongoing_service_records(organization_id,project_id,project_service_id,handover_record_id,documentation_record_id,stabilization_record_id,observation_record_id,deployment_record_id,implementation_record_id,delivery_activation_id,entitlement_id,ongoing_service_reference,idempotency_key,service_scope_snapshot,billing_mode,created_by) values(handover.organization_id,handover.project_id,handover.project_service_id,handover.id,documentation.id,stabilization.id,observation.id,deployment.id,implementation.id,activation.id,entitlement.id,ref,idem,coalesce(p_service_scope_snapshot,'{}'::jsonb),mode,actor_id) returning * into created;
 perform private.record_ongoing_service_audit('ongoing_service_initialized',created.organization_id,created.project_id,created.project_service_id,created.handover_record_id,created.entitlement_id,created.id,jsonb_build_object('billing_mode',created.billing_mode)); return created;
end; $$;
create or replace function public.pause_ongoing_service_record(p_ongoing_service_record_id uuid,p_expected_status text default 'ACTIVE',p_status_reason text default null) returns public.ongoing_service_records language plpgsql security definer set search_path=public,private,pg_temp as $$ declare target public.ongoing_service_records; changed public.ongoing_service_records; begin select * into target from public.ongoing_service_records where id=p_ongoing_service_record_id for update; if not found then raise exception using errcode='P0002',message='Ongoing-service record was not found.'; end if; if not private.commercial_owner(target.organization_id) then raise exception using errcode='42501',message='Only the organization owner can pause ongoing service.'; end if; if upper(btrim(coalesce(p_expected_status,'')))<>target.status or target.status<>'ACTIVE' then raise exception using errcode='40001',message='Ongoing-service record is not active or has changed. Refresh and retry.'; end if; update public.ongoing_service_records set status='PAUSED',paused_at=timezone('utc',now()),status_reason=nullif(btrim(p_status_reason),'') where id=target.id returning * into changed; perform private.record_ongoing_service_audit('ongoing_service_paused',changed.organization_id,changed.project_id,changed.project_service_id,changed.handover_record_id,changed.entitlement_id,changed.id,jsonb_build_object('previous_status',target.status)); return changed; end; $$;
create or replace function public.resume_ongoing_service_record(p_ongoing_service_record_id uuid,p_expected_status text default 'PAUSED',p_status_reason text default null) returns public.ongoing_service_records language plpgsql security definer set search_path=public,private,pg_temp as $$ declare target public.ongoing_service_records; changed public.ongoing_service_records; begin select * into target from public.ongoing_service_records where id=p_ongoing_service_record_id for update; if not found then raise exception using errcode='P0002',message='Ongoing-service record was not found.'; end if; if not private.commercial_owner(target.organization_id) then raise exception using errcode='42501',message='Only the organization owner can resume ongoing service.'; end if; if upper(btrim(coalesce(p_expected_status,'')))<>target.status or target.status<>'PAUSED' then raise exception using errcode='40001',message='Ongoing-service record is not paused or has changed. Refresh and retry.'; end if; update public.ongoing_service_records set status='ACTIVE',paused_at=null,status_reason=nullif(btrim(p_status_reason),'') where id=target.id returning * into changed; perform private.record_ongoing_service_audit('ongoing_service_resumed',changed.organization_id,changed.project_id,changed.project_service_id,changed.handover_record_id,changed.entitlement_id,changed.id,jsonb_build_object('previous_status',target.status)); return changed; end; $$;
create or replace function public.complete_ongoing_service_record(p_ongoing_service_record_id uuid,p_expected_status text default 'ACTIVE',p_status_reason text default null) returns public.ongoing_service_records language plpgsql security definer set search_path=public,private,pg_temp as $$ declare target public.ongoing_service_records; changed public.ongoing_service_records; begin select * into target from public.ongoing_service_records where id=p_ongoing_service_record_id for update; if not found then raise exception using errcode='P0002',message='Ongoing-service record was not found.'; end if; if not private.commercial_owner(target.organization_id) then raise exception using errcode='42501',message='Only the organization owner can complete ongoing service.'; end if; if upper(btrim(coalesce(p_expected_status,'')))<>target.status or target.status not in('ACTIVE','PAUSED') then raise exception using errcode='40001',message='Ongoing-service record is not active/paused or has changed. Refresh and retry.'; end if; update public.ongoing_service_records set status='COMPLETED',completed_at=timezone('utc',now()),status_reason=nullif(btrim(p_status_reason),'') where id=target.id returning * into changed; perform private.record_ongoing_service_audit('ongoing_service_completed',changed.organization_id,changed.project_id,changed.project_service_id,changed.handover_record_id,changed.entitlement_id,changed.id,jsonb_build_object('previous_status',target.status)); return changed; end; $$;
create or replace function public.cancel_ongoing_service_record(p_ongoing_service_record_id uuid,p_expected_status text default 'ACTIVE',p_status_reason text default null) returns public.ongoing_service_records language plpgsql security definer set search_path=public,private,pg_temp as $$ declare target public.ongoing_service_records; changed public.ongoing_service_records; begin select * into target from public.ongoing_service_records where id=p_ongoing_service_record_id for update; if not found then raise exception using errcode='P0002',message='Ongoing-service record was not found.'; end if; if not private.commercial_owner(target.organization_id) then raise exception using errcode='42501',message='Only the organization owner can cancel ongoing service.'; end if; if upper(btrim(coalesce(p_expected_status,'')))<>target.status or target.status not in('ACTIVE','PAUSED') then raise exception using errcode='40001',message='Ongoing-service record is not active/paused or has changed. Refresh and retry.'; end if; update public.ongoing_service_records set status='CANCELLED',cancelled_at=timezone('utc',now()),status_reason=nullif(btrim(p_status_reason),'') where id=target.id returning * into changed; perform private.record_ongoing_service_audit('ongoing_service_cancelled',changed.organization_id,changed.project_id,changed.project_service_id,changed.handover_record_id,changed.entitlement_id,changed.id,jsonb_build_object('previous_status',target.status)); return changed; end; $$;
create or replace function private.prevent_ongoing_service_mutation() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin if tg_op='DELETE' then raise exception using errcode='42501',message='Ongoing-service history cannot be deleted.'; end if; if old.id is distinct from new.id or old.organization_id is distinct from new.organization_id or old.project_id is distinct from new.project_id or old.project_service_id is distinct from new.project_service_id or old.handover_record_id is distinct from new.handover_record_id or old.documentation_record_id is distinct from new.documentation_record_id or old.stabilization_record_id is distinct from new.stabilization_record_id or old.observation_record_id is distinct from new.observation_record_id or old.deployment_record_id is distinct from new.deployment_record_id or old.implementation_record_id is distinct from new.implementation_record_id or old.delivery_activation_id is distinct from new.delivery_activation_id or old.entitlement_id is distinct from new.entitlement_id or old.ongoing_service_reference is distinct from new.ongoing_service_reference or old.idempotency_key is distinct from new.idempotency_key or old.service_scope_snapshot is distinct from new.service_scope_snapshot or old.billing_mode is distinct from new.billing_mode or old.started_at is distinct from new.started_at or old.created_by is distinct from new.created_by or old.created_at is distinct from new.created_at then raise exception using errcode='42501',message='Ongoing-service source and scope fields are immutable.'; end if; if new.status is distinct from old.status and not((old.status='ACTIVE' and new.status in('PAUSED','COMPLETED','CANCELLED')) or (old.status='PAUSED' and new.status in('ACTIVE','COMPLETED','CANCELLED'))) then raise exception using errcode='22023',message='Ongoing-service lifecycle transition is not allowed.'; end if; return new; end; $$;
revoke all on function private.prevent_ongoing_service_mutation() from public;
revoke execute on function private.prevent_ongoing_service_mutation() from anon;
drop trigger if exists prevent_ongoing_service_mutation on public.ongoing_service_records;
create trigger prevent_ongoing_service_mutation before update or delete on public.ongoing_service_records for each row execute procedure private.prevent_ongoing_service_mutation();
revoke all on function public.initialize_ongoing_service(uuid,text,text,jsonb,text,uuid) from public;
revoke execute on function public.initialize_ongoing_service(uuid,text,text,jsonb,text,uuid) from anon,authenticated;
grant execute on function public.initialize_ongoing_service(uuid,text,text,jsonb,text,uuid) to service_role;
revoke all on function public.pause_ongoing_service_record(uuid,text,text) from public;
revoke all on function public.resume_ongoing_service_record(uuid,text,text) from public;
revoke all on function public.complete_ongoing_service_record(uuid,text,text) from public;
revoke all on function public.cancel_ongoing_service_record(uuid,text,text) from public;
revoke execute on function public.pause_ongoing_service_record(uuid,text,text) from anon;
revoke execute on function public.resume_ongoing_service_record(uuid,text,text) from anon;
revoke execute on function public.complete_ongoing_service_record(uuid,text,text) from anon;
revoke execute on function public.cancel_ongoing_service_record(uuid,text,text) from anon;
grant execute on function public.pause_ongoing_service_record(uuid,text,text) to authenticated;
grant execute on function public.resume_ongoing_service_record(uuid,text,text) to authenticated;
grant execute on function public.complete_ongoing_service_record(uuid,text,text) to authenticated;
grant execute on function public.cancel_ongoing_service_record(uuid,text,text) to authenticated;
alter table public.ongoing_service_records enable row level security;
create policy "Accessible members can view ongoing service records" on public.ongoing_service_records for select to authenticated using(private.has_organization_role(organization_id,'MEMBER') and private.has_project_access(project_id));
create policy "Ongoing service inserts require trusted functions" on public.ongoing_service_records for insert to authenticated with check(false);
create policy "Ongoing service updates require trusted functions" on public.ongoing_service_records for update to authenticated using(false) with check(false);
create policy "Ongoing service deletes are disabled" on public.ongoing_service_records for delete to authenticated using(false);
comment on table public.ongoing_service_records is 'Optional separately paid post-handover ongoing service lifecycle record. Billing execution, subscriptions, and payment collection are outside this foundation.';
comment on function public.initialize_ongoing_service(uuid,text,text,jsonb,text,uuid) is 'Service-role-only ongoing service initialization boundary requiring a completed handover and complete active upstream chain.';
